from pathlib import Path
import re
s=Path('docs/study-original.html').read_text()
s=s.replace("if(new Set(facts.map(f=>f.detail.toLowerCase())).size!==5)","if(new Set(facts.map(f=>f.detail.normalize('NFKC').toLowerCase())).size!==5||new Set(facts.map(f=>f.term.normalize('NFKC').toLowerCase())).size!==5)")
s=s.replace('Lima fakta pertama mesti mempunyai penerangan berbeza supaya setiap soalan ada satu jawapan.','Lima fakta pertama mesti mempunyai istilah dan penerangan yang berbeza supaya setiap soalan ada satu jawapan.')
s=s.replace('scrollIntoView({behavior:\'smooth\'})','scrollIntoView({behavior:\'instant\'})')
s=s.replace('<head>','<head><meta name="robots" content="noindex,follow">')
s=s.replace('</body>',"<script>new ResizeObserver(()=>parent.postMessage({type:'study-size',height:document.documentElement.scrollHeight},'*')).observe(document.body);</script></body>")
Path('public/tools').mkdir(exist_ok=True)
Path('public/tools/study-lab.html').write_text(s)
mapping={'lang="ms"':'lang="en"','Nota masuk.':'Notes in.','Kuiz keluar.':'Quiz out.','Tukar nota Bahasa Melayu kepada lima kad ulang kaji dan lima soalan latihan. Versi HTML ini berfungsi tanpa internet dan':'Turn your notes into five flashcards and five practice questions. This HTML tool works without internet and','tidak menggunakan AI':'does not use AI','MOD OFFLINE · TANPA API':'OFFLINE MODE · NO API','01 / Masukkan nota':'01 / Enter notes','Untuk hasil tepat, masukkan sekurang-kurangnya lima fakta pada baris berasingan, dalam format':'For reliable matching, enter at least five facts on separate lines in the format','Istilah: penerangan':'Term: explanation','Contoh:':'Example:','Nota pelajaran':'Study notes','aksara':'characters','Jana latihan':'Build practice','02 / Flashcard':'02 / Flashcards','5 KAD · EKSTRAK NOTA':'5 CARDS · FROM YOUR NOTES','Tekan “Lihat jawapan” untuk membuka kad.':'Press “Show answer” to reveal a card.','Lihat jawapan':'Show answer','Sembunyikan jawapan':'Hide answer','03 / Kuiz':'03 / Quiz','5 SOALAN':'5 QUESTIONS','Setiap soalan mempunyai satu jawapan tepat berdasarkan nota anda. Pilihan lain ialah penerangan bagi istilah lain dalam nota yang sama.':'Each question has one correct answer based on your notes. Other options come from other terms in the same notes.','Cuba semula':'Try again','Nota baharu':'New notes','Apakah maksud':'What is the meaning of','Betul!':'Correct!','Belum tepat.':'Not quite.','Markah:':'Score:','Nota terlalu panjang.':'Notes are too long.','Perlu sekurang-kurangnya lima baris fakta sah dengan format Istilah: penerangan. Tiada fakta akan direka.':'Enter at least five valid Term: explanation lines. No facts will be invented.','Lima fakta pertama mesti mempunyai istilah dan penerangan yang berbeza supaya setiap soalan ada satu jawapan.':'The first five facts need unique terms and explanations so each question has one correct answer.','Kad ${i+1}':'Card ${i+1}'}
for k in sorted(mapping,key=len,reverse=True):s=s.replace(k,mapping[k])
Path('public/tools/study-lab-en.html').write_text(s)
